gaVC(){return"\u0641\u0634\u0644 \u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0639\u0642\u062f \u2014 \u0642\u062f \u064a\u0643\u0648\u0646 \u0631\u0635\u064a\u062f\u0643 \u063a\u064a\u0631 \u0643\u0627\u0641\u064d."},
gwJ(){return"\u0627\u0644\u0637\u0627\u0642\u0645 \u0627\u0644\u0641\u0646\u064a"},
gYV(){return"\u062a\u0639\u0630\u0631 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u0631\u0639\u0627\u064a\u0627\u062a"},
gYW(){return"\u0641\u0634\u0644 \u0627\u0644\u062a\u0648\u0642\u064a\u0639 \u2014 \u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627"},
gp6(){return"\u0627\u0644\u0631\u0639\u0627\u064a\u0627\u062a"},
gaAG(){return"\u062a\u0628\u062f\u0623 \u0628\u0639\u062f"},
gaAI(){return"\u0627\u0644\u0637\u0642\u0633"},
gaAH(){return"\u0627\u0644\u062d\u0643\u0645"},
gPW(){return"\u0627\u0644\u0645\u0624\u062a\u0645\u0631 \u0627\u0644\u0635\u062d\u0641\u064a"},
gaKm(){return"\u0648\u0627\u062b\u0642"},
gaKn(){return"\u0627\u0644\u062e\u0635\u0645 \u0633\u064a\u0633\u0645\u0639 \u0630\u0644\u0643"},
gaKo(){return"\u062f\u0628\u0644\u0648\u0645\u0627\u0633\u064a"},
gaKp(){return"\u0644\u0646 \u064a\u0646\u0632\u0639\u062c \u0623\u062d\u062f"},
gaKq(){return"\u0645\u062d\u0641\u0651\u0632"},
gaKr(){return"\u0641\u0631\u064a\u0642\u0643 \u0633\u064a\u0633\u0645\u0639 \u0647\u0630\u0627"},
gaKs(){return"\u0638\u0631\u064a\u0641"},
gaKt(){return"\u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u062a\u062d\u0628\u0647\u060c \u0644\u0643\u0646 \u0644\u064a\u0633 \u0627\u0644\u062c\u0645\u064a\u0639"},
